<?php
 namespace Pterodactyl\Services\Dezerx\Importer; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class DestinationIndex { private array $folders = []; public function __construct( private readonly ServerFiles $node, private readonly string $root, ) { } public function has(string $folder, string $name): bool { $key = $folder === '.' ? '' : $folder; if (!array_key_exists($key, $this->folders)) { $this->folders[$key] = array_values(array_map( fn (array $entry) => (string) ($entry['name'] ?? ''), $this->node->listFiles($this->path($key)) ?? [], )); } return in_array($name, $this->folders[$key], true); } private function path(string $folder): string { if ($folder === '') { return $this->root; } return $this->root === '/' ? '/' . $folder : $this->root . '/' . $folder; } } 